package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for OpenMapRealMatrix.setEntry
 */
public class OpenMapRealMatrix_setEntry_TriageGen1Test {

    private OpenMapRealMatrix matrix;
    private static final int ROWS = 5;
    private static final int COLS = 5;

    @Before
    public void setUp() {
        matrix = new OpenMapRealMatrix(ROWS, COLS);
    }

    @Test
    public void testSetEntry_PositiveValue() {
        int row = 1;
        int col = 2;
        double value = 10.5;

        matrix.setEntry(row, col, value);

        assertEquals("Value should be set correctly", value, matrix.getEntry(row, col), 1e-10);
    }














}

