package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for OpenMapRealMatrix.setEntry
 */
public class OpenMapRealMatrix_setEntry_TriageGen1Test {

    private OpenMapRealMatrix matrix;
    private static final int ROWS = 5;
    private static final int COLS = 5;

    @Before
    public void setUp() {
        matrix = new OpenMapRealMatrix(ROWS, COLS);
    }





    @Test
    public void testSetEntry_ZeroValue_AddsNew() {
        // First ensure it's not zero (to test the removal path)
        int row = 2;
        int col = 2;
        matrix.setEntry(row, col, 1.0);

        // Setting to 0.0 should trigger the 'remove' branch
        matrix.setEntry(row, col, 0.0);

        assertEquals("Value should be 0.0 after setting to zero", 0.0, matrix.getEntry(row, col), 1e-10);
        // In an OpenMapRealMatrix, setting to 0.0 effectively removes the entry from the internal map
    }










}

